import sys
import heapq

def main():
    import sys
    import heapq
    input = sys.stdin.read().split()
    n = int(input[0])
    nodes = [(int(input[2*i+1]), int(input[2*i+2])) for i in range(n)]

    def dist(p1, p2):
        return ((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2) ** 0.5

    edges = []
    for i in range(n):
        for j in range(i + 1, n):
            if nodes[i][1] > nodes[j][1]:
                heapq.heappush(edges, (dist(nodes[i], nodes[j]), i, j))
            elif nodes[j][1] > nodes[i][1]:
                heapq.heappush(edges, (dist(nodes[j], nodes[i]), j, i))

    parent = list(range(n))
    rank = [0] * n

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rootX = find(x)
        rootY = find(y)
        if rootX != rootY:
            if rank[rootX] > rank[rootY]:
                parent[rootY] = rootX
            elif rank[rootX] < rank[rootY]:
                parent[rootX] = rootY
            else:
                parent[rootY] = rootX
                rank[rootX] += 1
            return True
        return False

    mst_weight = 0
    edge_count = 0
    degree = [0] * n

    while edges:
        weight, u, v = heapq.heappop(edges)
        if union(u, v):
            mst_weight += weight
            edge_count += 1
            degree[u] += 1
            degree[v] += 1
            if degree[u] > 2 or degree[v] > 2:
                print('-1')
                return

    if edge_count == n - 1:
        print(f'{mst_weight:.10f}')
    else:
        print('-1')

main()
